// src/button-art.js
var BUTTON_ART = Object.freeze({
  lock: btn_lock_default,
  unlock: btn_unlock_default,
  start: btn_start_default,
  horn: btn_horn_default
});
function artForSlot(slot) {
  switch (slot) {
    case "btn_unlock":
      return { src: BUTTON_ART.unlock, wide: false };
    case "btn_lock":
      return { src: BUTTON_ART.lock, wide: false };
    case "sw_engine":
      return { src: BUTTON_ART.start, wide: false };
    case "sw_honk":
      return { src: BUTTON_ART.horn, wide: true };
    default:
      return null;
  }
}

